steps.sampleSolution:
type Pedido struct {
    ID    int     `json:"id"`
    Total float64 `json:"total"`
}
func Primeiro[T any](itens []T) (T, bool) {
    var zero T
    if len(itens) == 0 {
        return zero, false
    }
    return itens[0], true
}
